import{z as p,x as A,o as t,c as d,q as E,j as n,D as e,d as o,s,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"列存与 PAX","description":"","frontmatter":{"title":"列存与 PAX","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/columnar-pax.md","filePath":"cs/columnar-pax.md","lastUpdated":1791413859000}'),B={name:"cs/columnar-pax.md"};function c(m,a,P,h,u,D){const l=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=E('<h1 id="列存与-pax" tabindex="-1">列存与 PAX <a class="header-anchor" href="#列存与-pax" aria-label="Permalink to &quot;列存与 PAX&quot;">​</a></h1><div class="epigraph"><p>列存按属性切文件，扫描只读需要的列；PAX 在页内按列摆放，保持页为 I/O 单位，减少行组装的跨页随机。</p><footer>—— 据 Copeland and Khoshafian DSM；Ailamaki et al. PAX, VLDB 2001；C-Store / MonetDB</footer></div><p><a href="/cs/leveled-tiered-compaction">上一课</a>决定 LSM 文件如何分层。本课不调倍率。缺口是页/文件<strong>内部布局</strong>：行存一行连续，OLAP 扫描浪费带宽在无用列上。列存（DSM）每列一堆文件，延迟物化自然。PAX（partition attributes across）折中：一页里所有列的一段行，页间仍是行组。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分析查询常 <code>SUM(a) WHERE b&gt;</code>，只需两列。行页把整行带进缓存。纯列存：谓词列与度量列分别顺序扫，组装用位置对齐。跨列更新、点查、宽行插入在纯列上变随机或写放大。缺口是 <strong>OLAP 布局 vs OLTP 行页</strong>，不是新 SQL。</p><p>PAX：一个 row group 放进页，页内各列分别数组。缓存行上扫一列仍顺序，点查一行在同一页内可取齐列。C-Store、Parquet 的 row group 是同一思想的文件级版本。</p><p><span class="marginnote">术语翻译：NSM（行存）像记笔记本——一个人的所有信息连续写在一起；DSM（列存）像 Excel——同一属性竖着排一整列。前者适合「取出这一整行」，后者适合「对某一列算总数」，PAX 则是每页内部按 Excel 摆、页与页之间仍按笔记本分章。</span></p><p><span class="marginnote">Ailamaki, DeWitt, Hill, Skounakis，VLDB 2001 PAX。Copeland and Khoshafian 分解存储模型。Stonebraker et al. C-Store。本课布局；压缩下一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>行页：槽+记录。列文件：每列块+位置对齐或每列自有空值位图。PAX 页：页头、各列偏移、列数据。执行器向量化从 PAX 或列块直接填列向量，少经行中间态。</p><p><span class="marginnote">数字实例：<code>SELECT SUM(a) FROM t WHERE b &gt; 10</code>，表有 100 列、100 万行、每格 8 字节。行页要把整行读进内存，约 100 万 × 800 字节 = 800 MB；列存只读 a、b 两列，约 100 万 × 16 字节 = 16 MB——差 50 倍，这就是分析查询偏爱列存的根由。</span></p><p>HTAP 后课用两份或可更新列存；本课只钉只读分析布局的动机。</p>',12)),(t(),n(i,null,{default:e(()=>[s(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20NSM%5B%22%E8%A1%8C%E9%A1%B5%22%5D%20--%3E%20WIDE%5B%22%E6%89%AB%E8%A1%8C%E5%B8%A6%E4%B8%8A%E6%97%A0%E7%94%A8%E5%88%97%22%5D%0A%20%20DSM%5B%22%E5%88%97%E6%96%87%E4%BB%B6%22%5D%20--%3E%20NARROW%5B%22%E5%8F%AA%E8%AF%BB%E9%9C%80%E8%A6%81%E7%9A%84%E5%88%97%22%5D%0A%20%20PAX%5B%22%E9%A1%B5%E5%86%85%E5%88%97%22%5D%20--%3E%20MIX%5B%22I%2FO%20%E5%8D%95%E4%BD%8D%E4%BB%8D%E6%98%AF%E9%A1%B5%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[o("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"更新：行页原地或 MVCC 新行；列存常写新列块或 delta 再合并（LSM+列）。缓冲池：列块缓存与行页缓存权重不同，替换策略仍要抗扫描污染。",-1)),(t(),n(i,null,{default:e(()=>[s(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20UP%5B%22%E6%9B%B4%E6%96%B0%E4%B8%80%E8%A1%8C%22%5D%20--%3E%20R%5B%22%E8%A1%8C%E9%A1%B5%E8%B7%AF%E5%BE%84%22%5D%0A%20%20UP%20--%3E%20C%5B%22%E5%88%97%E5%AD%98%E8%B7%AF%E5%BE%84%22%5D%0A%20%20R%20--%3E%20MVCC%5B%22%E5%8E%9F%E5%9C%B0%E6%94%B9%E6%88%96%E5%86%99%20MVCC%20%E6%96%B0%E8%A1%8C%22%5D%0A%20%20C%20--%3E%20DELTA%5B%22%E5%85%88%E5%86%99%20delta%20%E7%BC%93%E5%86%B2%E5%8C%BA%22%5D%0A%20%20DELTA%20--%3E%20MERGE%5B%22%E5%90%8E%E5%8F%B0%E5%90%88%E5%B9%B6%E6%88%90%E6%96%B0%E5%88%97%E5%9D%97%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=E('<p><span class="marginnote">为什么重要：列存改一行，理论上该行的每一列块都要动——所以引擎先写进 delta 区「记账」，后台再批量合并。初学者容易以为列存只是「省读」；实际上它把写一次的成本摊成了「写 delta + 后台合并」两段，这就是 HTAP 系统要专门解决的事。</span></p><p>连接：列存上延迟物化用位置；shuffle 只发键列。与 exchange 课对齐。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲字典/RLE。也不把宽列 Bigtable 当分析列存——宽列是稀疏行键模型，后课。PAX 不是「有了就不需要 Parquet」；文件格式课会把 row group 标准化。</p><p>后课默认：分析扫描用列或 PAX；点查可用行或覆盖索引。列压缩：编码使列块更小、跳过更狠。</p><p>布局服务访问模式。同一 SQL 在不同布局上计划常数不同，要重校准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>列存减分析 I/O；PAX 在页内列化以免点查跨页。</li><li>更新与点查是列存的代价面。</li><li>列压缩下一课：字典、RLE、位打包。</li><li>出处：Copeland and Khoshafian；Ailamaki et al. PAX；C-Store。</li></ul>',8))])}const f=p(B,[["render",c]]);export{S as __pageData,f as default};
